-- =============================================
-- filesystem_upload_task 分片上传任务表
--
-- 数据库兼容矩阵:
--   ✅ MySQL 5.7+ (使用 AUTO_INCREMENT)
--   ✅ H2 2.x (MODE=MySQL 下支持 AUTO_INCREMENT)
--   ⚠️  PostgreSQL 不支持 (需改用 GENERATED BY DEFAULT AS IDENTITY)
--
-- 通用化策略:
--   1. 不使用数据库专属语法 (ENGINE/CHARSET/COLLATE/COMMENT 子句)
--   2. 不使用 ON UPDATE CURRENT_TIMESTAMP (H2 不支持)
--   3. 使用标准 ANSI SQL 类型 (BIGINT/VARCHAR/INT/TIMESTAMP)
--   4. 列注释放在 SQL 注释行, 不依赖 COMMENT 子句
--   5. 索引使用标准 CREATE INDEX
--   6. 默认值使用 CURRENT_TIMESTAMP (三库通用)
--   7. 主键用 BIGINT NOT NULL AUTO_INCREMENT (MySQL/H2 通用)
--
-- 更新时间策略:
--   应用层 (MetaObjectHandler / Service) 负责 update_time 维护,
--   避免数据库触发器差异。
-- =============================================

CREATE TABLE IF NOT EXISTS filesystem_upload_task (
    filesystem_upload_task_id           BIGINT       NOT NULL AUTO_INCREMENT,    -- 主键ID
    filesystem_upload_task_upload_id    VARCHAR(64)  NOT NULL,                  -- 上传任务ID (ULID)
    filesystem_upload_task_file_name    VARCHAR(255) NOT NULL,                  -- 文件名称
    filesystem_upload_task_original_name VARCHAR(255) NOT NULL,                 -- 文件原始名称
    filesystem_upload_task_file_size    BIGINT       NOT NULL,                  -- 文件大小 (字节)
    filesystem_upload_task_chunk_size   BIGINT       NOT NULL,                  -- 分片大小 (字节)
    filesystem_upload_task_total_chunks  INT          NOT NULL,                  -- 总分片数
    filesystem_upload_task_uploaded_chunks INT       NOT NULL DEFAULT 0,        -- 已上传分片数
    filesystem_upload_task_storage_type VARCHAR(64)  NOT NULL,                  -- 存储类型 (local/minio/oss/cos/...)
    filesystem_upload_task_bucket       VARCHAR(255) NOT NULL,                  -- 存储桶
    filesystem_upload_task_key          VARCHAR(500) NOT NULL,                  -- 文件 Key
    filesystem_upload_task_content_type VARCHAR(128),                           -- 内容类型 (MIME)
    filesystem_upload_task_status       INT          NOT NULL DEFAULT 0,        -- 状态: 0-待上传, 1-上传中, 2-待合并, 3-合并中, 4-已完成, -1-失败, -2-已取消
    filesystem_upload_task_error_message VARCHAR(1000),                         -- 错误信息
    filesystem_upload_task_file_url     VARCHAR(1000),                         -- 已完成文件 URL
    filesystem_upload_task_start_time   TIMESTAMP,                              -- 上传开始时间
    filesystem_upload_task_complete_time TIMESTAMP,                             -- 上传完成时间
    create_by                          INT,                                    -- 创建人 ID
    create_name                         VARCHAR(255),                           -- 创建人姓名
    create_time                        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- 创建时间
    update_time                        TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- 更新时间 (应用层维护)
    update_by                          INT,                                    -- 更新人 ID
    update_name                         VARCHAR(255),                           -- 更新人姓名
    -- 主键约束
    PRIMARY KEY (filesystem_upload_task_id),
    -- 唯一约束: upload_id 业务唯一
    CONSTRAINT uk_filesystem_upload_task_upload_id UNIQUE (filesystem_upload_task_upload_id)
);

-- 索引 (MySQL 8.0+ 不支持 CREATE INDEX IF NOT EXISTS, 这里省略 IF NOT EXISTS;
--  重复执行时由 datasource-starter 的版本记录表防重, 不需要 IF NOT EXISTS)
CREATE INDEX idx_filesystem_upload_task_status     ON filesystem_upload_task (filesystem_upload_task_status);
CREATE INDEX idx_filesystem_upload_task_create_time ON filesystem_upload_task (create_time);
CREATE INDEX idx_filesystem_upload_task_storage     ON filesystem_upload_task (filesystem_upload_task_storage_type, filesystem_upload_task_bucket);
